          "نعم — الجمع بين الحشمة وإدارة الحرارة مهارة قائمة بذاتها، منفصلة عن كل منهما بمفرده. نفس التغطية — ملابس فضفاضة تغطي المناطق نفسها في أي شهر آخر — يمكن تنفيذها بطرق إما محتملة أو مرهقة في حرارة 43 درجة، والفرق يكمن في القماش والقصّة لا في التغطية نفسها. الألوان الداكنة تمتص حرارة أكبر خلال المسافات القصيرة بين الأماكن المكيّفة، وهذه المسافات تتراكم أكثر مما يتوقع الناس. حمل طبقة خفيفة إضافية للأماكن شديدة التبريد كالمولات والمساجد يستحق العناء حتى في حرارة 45 درجة بالخارج.",
